        accent: '#8A9090', accentGlow: 'rgba(138,144,144,0.22)', accentDim: '#3A4040',
        floorColor: '#1E2020', floorAlt: '#252828', wallDark: '#0C0E0E', wallLight: '#141818',
        bg: 'radial-gradient(circle at 60% 40%, #141818 0%, #080A0A 70%)', ambient: 'embers',
